function multiplySparse(a: number[][], b: number[][]): number[][] {
  const m = a.length, k = b.length, n = b[0].length;
  // nonzero (column, value) pairs for each row of b
  const rowsB: [number, number][][] = b.map(row => {
    const list: [number, number][] = [];
    row.forEach((v, j) => { if (v !== 0) list.push([j, v]); });
    return list;
  });
  const out: number[][] = Array.from({ length: m }, () => new Array(n).fill(0));
  for (let i = 0; i < m; i++) {
    for (let t = 0; t < k; t++) {
      const x = a[i][t];
      if (x === 0) continue;
      for (const [j, v] of rowsB[t]) out[i][j] += x * v;
    }
  }
  return out;
}

