        rows_b = [[(j, v) for j, v in enumerate(row) if v] for row in b]
        out = [[0] * n for _ in range(m)]
        for i in range(m):
            target = out[i]
            for t, x in enumerate(a[i]):
                if x:
                    for j, v in rows_b[t]:
                        target[j] += x * v
        return out

